-- NGO/private wave: collection sources for the 15 funders registered 2026-11-12 (grants.set_collection, label ngo-wave-2026-11-12).
select grants.set_collection('b6fda0d5-1a63-4c0d-81f3-daa1b46d35b5', '{"adapter": "html", "adapter_config": {}, "url": "https://www.waverleystreet.org/about", "feed_url": null, "note": "No public call list exists: Waverley Street Foundation states on its FAQ that it does not accept unsolicited proposals, and it is a spend-down foundation that funds by invitation. The About page (with its FAQ) is watched twice a day, so a change such as a new call or an opened application route is flagged for review.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- Waverley Street Foundation
select grants.set_collection('c59e28a1-92f3-4158-8011-0f257f8aeeab', '{"adapter": "html", "adapter_config": {"list": {"url": "https://www.nationalacademies.org/programs/PGA-GLOBAL-22-03/updates", "item": "div[data-component=\"card:generic\"]", "title": "p.f-heading-05", "match": "Now Open|Call for|Applications? open|Nominations? open|Open for (?:nominations|applications)", "skip": "Winner|Feature Story"}, "max_items": 10, "auto_vet": false}, "url": "https://www.nationalacademies.org/programs/PGA-GLOBAL-22-03/application-process", "feed_url": null, "note": "Reads every call announcement (''... Now Open'', ''Call for ...'') from the National Academies program updates page for this prize, which is the official program page and lists each edition''s opening, twice a day.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- Frontiers Planet Prize (National Academies of Sciences, Engi
select grants.set_collection('610978d8-7dab-416b-8ea1-9615461de4dd', '{"adapter": "html", "adapter_config": {}, "url": "https://granthamfoundation.org/grants-investments/", "feed_url": null, "note": "No public call list exists: the foundation works by invitation only and does not consider proposals with indirect costs above 10%. The Grants & Investments page is watched and any change is flagged for review, so a future open call would appear there or on the thinking page.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- Grantham Foundation for the Protection of the Environment
select grants.set_collection('894bf54c-8dca-4673-a356-14406185b0e3', '{"adapter": "html", "adapter_config": {}, "url": "https://11thhourproject.org/food-and-agriculture/", "feed_url": null, "note": "No public call for proposals exists: the Foundation''s Inbound Inquiries Policy (/about/) and FAQ say it does not accept unsolicited proposals and funds through its network. The program page is watched twice a day as a change feed, and any new text is flagged for review. The WordPress /feed/ is a blog feed (one 2025 post), so it is not used as a call source. No deadlines are collected.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- The 11th Hour Project (Schmidt Family Foundation)
select grants.set_collection('af4f0a9f-a40d-4907-8716-a76ce50bb1f9', '{"adapter": "html", "adapter_config": {"auto_vet": true, "self": {"title": "W. M. Keck Foundation Research Program (Basic Science Research)", "deadline_regex": "\\(([A-Za-z]+ \\d{1,2}, \\d{4})\\)"}}, "url": "https://www.wmkeck.org/research-overview/", "feed_url": null, "note": "Reads the Research Program''s two named cycle deadlines (the second Monday after Thanksgiving and the first Monday after Memorial Day, each printed with its date in parentheses) from the program''s own overview page, twice a day; the nearest future date is the open call.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- W. M. Keck Foundation
select grants.set_collection('c1a8d745-6a95-40b6-85ff-793966e33dbe', '{"adapter": "json_api", "adapter_config": {"url": "https://gulbenkian.pt/wp-json/wp/v2/grant?per_page=100", "method": "GET", "items_path": "$", "also_page": true, "map": {"external_id": "id", "title": "title.rendered", "url": "link", "description": "acf.description", "deadline": "acf.applications.0.end_date", "open_date": "acf.applications.0.start_date"}, "filter": {"any": ["clim", "energ", "água", "agua", "ambiental", "biodivers", "natureza", "sustentab", "alimentar", "agrícol", "agricult", "renov", "conservação", "hídric"], "fields": "title+description"}, "max_items": 40, "auto_vet": false}, "url": "https://gulbenkian.pt/en/the-foundation/gulbenkian-prize-for-humanity/", "feed_url": null, "note": "Reads the Foundation''s public WordPress grants list (wp-json grant type, every published call with its application start and end dates) twice a day and keeps the climate, energy, water, agriculture and environment calls.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- Calouste Gulbenkian Foundation
select grants.set_collection('1135c5ca-a4d2-49ba-9772-188a3339a306', '{"adapter": "html", "adapter_config": {}, "url": "https://foodplanetprize.org/foundation/prize/", "feed_url": null, "note": "Page watch only: the Food Planet Prize is an annual award, not a grant call. Nominations are accepted year-round through the website form with no published deadline (the page advises nominating before May for the following year''s cycle, which is guidance, not a dated call), and the funder publishes no open call list.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- Curt Bergfors Foundation (Food Planet Prize)
select grants.set_collection('822f12b1-dedd-4c1f-9d60-d1e21abbd7b1', '{"adapter": "html", "adapter_config": {"auto_vet": true, "self": {"title": "2026 Google Carbon Removal and Superpollutant Elimination R&D Awards", "deadline_regex": "applications\\s+close\\s+([A-Z][a-z]+\\.?\\s+\\d{1,2}(?:st|nd|rd|th)?,?\\s+\\d{4})"}}, "url": "https://research.google/programs-and-events/2026-google-carbon-removal-and-superpollutant-elimination-rd-awards/", "feed_url": null, "note": "Reads the program''s own page twice a day for a labeled ''applications close'' date and creates one call per cycle (external_id cycle:<deadline year>) only while that date is in the future; the 2026 call closed Sept. 25, 2026, so nothing is shown today (0 items, correct for a closed call).", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- Google Research
select grants.set_collection('ec3477b4-a014-4d94-b2c2-407da5e2562b', '{"adapter": "html", "adapter_config": {}, "url": "https://www.google.org/impact-challenges/ai-science/", "feed_url": null, "note": "No call is collected: this page lists the announced recipients of the 2026 $36M open call (its deadline was spring 2026), and no later cycle or deadline is published on any official page. Recipients are awards, not calls, so they are not rows. The program page is watched twice a day; a new cycle, a deadline or an apply link appearing there is flagged for review.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- Google.org
select grants.set_collection('fa09bcf7-0321-45d7-83cb-0557d60494fd', '{"adapter": "html", "adapter_config": {}, "url": "https://www.pepsico.com/our-impact/philanthropy/pepsico-foundation", "feed_url": null, "note": "Page watch. pepsico.com refused a desktop fetch (HTTP 403) on 2026-11-12 but the edge function reads it (health ok). The Foundation funds partners it selects and publishes no open calls; no sitemap, feed or JSON list of calls exists.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- PepsiCo Foundation
select grants.set_collection('002801a7-0e64-4f21-b0ce-b6581f2b4d74', '{"adapter": "html", "adapter_config": {}, "url": "https://www.coca-colacompany.com/foundation", "feed_url": null, "note": "Page watch only: the Foundation does not publish calls for proposals and states it does not accept unsolicited grant proposals; its SmartSimple request portal says applicants are invited by email, so there is no public call list to collect.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- The Coca-Cola Foundation
select grants.set_collection('6cae3342-97a8-4683-9f6f-ef2b2dfedd81', '{"adapter": "html", "adapter_config": {"auto_vet": true, "self": {"title": "Regenerative Agriculture Targeted RFP (Greenacres Foundation)", "deadline_regex": "Application\\s+Deadline:\\s+([A-Z][a-z]+ \\d{1,2}, \\d{4})"}}, "url": "https://green-acres.org/research/regenerative-agriculture-research-grant/", "feed_url": null, "note": "Reads the dated 2027 Application Deadline of the Greenacres Foundation Regenerative Agriculture targeted RFP from its own page twice a day (plain HTML, no JavaScript).", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- Greenacres Foundation
select grants.set_collection('2aa89020-1edc-4ddc-bec9-e9ef304305cb', '{"adapter": "html", "adapter_config": {}, "url": "https://cfhfoundation.grantsmanagement08.com/?page_id=6", "feed_url": null, "note": "No call rows can be made: the two concept cycles (online application October 15 to December 22, and May 1 to June 15, each with its proposal and award dates) are published on the How to Apply page without a year, and the collector never invents a year, so no deadline can be dated from plain HTTP.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- Conservation, Food & Health Foundation
select grants.set_collection('a15aabd5-c77c-4c65-a093-abd8db4123da', '{"adapter": "html", "adapter_config": {"self": {"title": "PSIPW 13th Award (2028): nominations for the Creativity and Specialized Prizes", "deadline_regex": "(\\d{1,2}\\s+[A-Za-z]+\\s+\\d{4})\\s*:\\s*Deadline\\s+for\\s+receiving\\s+nominations"}, "auto_vet": true}, "url": "https://psipw.org/nomination-info/", "feed_url": null, "note": "Reads the one dated nomination cycle printed on the official Nomination Info page (\"31 December 2027: Deadline for receiving nominations\") twice a day; the call is open until that date and the same call updates in place if the date moves.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- Prince Sultan Bin Abdulaziz International Prize for Water (P
select grants.set_collection('70ccbae8-693a-41f5-aecb-5d6a87247a1d', '{"adapter": "html", "adapter_config": {"list": {"item": "div.fascia-link", "match": "2027 Eni Award", "title": "h2", "link": "a[href]", "date_label": true, "amount": false}, "auto_vet": true, "max_items": 10}, "url": "https://www.eni.com/en-IT/strategic-vision/innovation/eni-award.html", "feed_url": null, "note": "Eni''s own Eni Award page (server-rendered HTML, no JavaScript) carries the 2027 round block with the application deadline (November 20th, 2026; Eni for Innovation Recognitions January 31st, 2027) and its Apply link to the official candidate portal eniaward2027.net.", "verified": true}'::jsonb, 'ngo-wave-2026-11-12');  -- Eni S.p.A. (Eni Award)
